// content_pack.h - The content enhancement pack: Pulse.Content.exe (content
// search and duplicate finding agent) and Pulse.Document.exe (document text).
//
// Neither ships in the installer. pulse.exe downloads them on first use from
// the GitHub release of its own version into
//   %LOCALAPPDATA%\Pulse\packs\content\<version>\
// with PackInstaller, and before starting the agent checks that
// installed.json names exactly this version and that both files match the
// size and SHA-256 compiled in (content_pack_catalog.h, generated by
// pulse_pack_catalog from the files of the same build). That pins the agent
// to this app's protocol without a handshake. While verified, the files stay
// open without write or delete sharing, so they cannot change underneath.
//
// pdfium.dll stays in the install directory (Quick Look uses it too); the
// agent passes it on to Pulse.Document.exe through PULSE_PDFIUM_DIR, which
// only accepts the exact pdfium build pinned at configure time.
#pragma once
#include "../common/windows_compat.h"
#include "pack_catalog.h"
#include <cstdint>
#include <string>
#include <vector>

namespace pulse::app {

enum class ContentPackState : uint8_t {
    Bundled,      // Pulse.Content.exe beside pulse.exe (development builds)
    Ready,        // installed for this version and verified
    Missing,      // never installed
    Outdated,     // installed for another version of Pulse
    Damaged,      // this version, but a file is missing or does not match
    Unavailable,  // this build carries no catalog
};

// The release this build installs; file_count is 0 when it has none.
const PackRelease& ContentPackRelease() noexcept;
uint64_t ContentPackDownloadBytes(const PackRelease& release) noexcept;

struct ContentPackCheck {
    ContentPackState state = ContentPackState::Missing;
    std::wstring directory;  // version directory when Ready
};

// Checks <packs_root>\<release.key> against `release`. With `hold`, a Ready
// pack's files stay open (read sharing only) and their handles are appended;
// nothing is kept otherwise.
ContentPackCheck CheckContentPack(const PackRelease& release, const std::wstring& packs_root,
                                  std::vector<HANDLE>* hold = nullptr);

// The state for this process, with the result of a successful verification
// cached (and its files held) until ForgetVerifiedContentPack.
ContentPackState QueryContentPackState();
inline bool ContentPackInstallable(ContentPackState state) {
    return state == ContentPackState::Missing || state == ContentPackState::Outdated ||
           state == ContentPackState::Damaged;
}
// Pulse.Content.exe of a verified pack, else empty. Registered with
// index::SetContentAgentLocator by the app.
std::wstring LocateContentAgent();
// Drops the cached verification (after an install), releasing held files.
void ForgetVerifiedContentPack();

} // namespace pulse::app
